import { SignersController } from "../signers/index.js";
let WebComponentConnector = class WebComponentConnector extends LitElement {
    constructor() {
        super(...arguments);
        this.client = new ccc.ClientPublicTestnet();
        this.signersControllerInner = new SignersController(this);
        this.mainRef = createRef();
        this.bodyRef = createRef();
    }
    setClient(client) {
        this.client = client;
    }
    disconnect() {
        this.onClose(() => {
            this.walletName = undefined;
            this.signerName = undefined;
            this.saveConnection();
            void this.signer?.signer.disconnect();
        });
    }
    loadConnection() {
        const { signerName, walletName } = JSON.parse(window.localStorage.getItem("ccc-connection-info") ?? "{}");
        this.signerName = signerName;
        this.walletName = walletName;
    }
    saveConnection() {
        window.localStorage.setItem("ccc-connection-info", JSON.stringify({
            signerName: this.signerName,
            walletName: this.walletName,
        }));
    }
    connectedCallback() {
        super.connectedCallback();
        this.loadConnection();
    }
    willUpdate(changedProperties) {
        if (changedProperties.has("name") ||
            changedProperties.has("icon") ||
            changedProperties.has("client") ||
            changedProperties.has("signerFilter") ||
            changedProperties.has("preferredNetworks")) {
            void this.signersControllerInner.refresh();
        }
        if (changedProperties.has("walletName") ||
            changedProperties.has("signerName")) {
            this.refreshSigner();
        }
        this.dispatchEvent(new Event("willUpdate"));
    }
    refreshSigner() {
        const wallet = this.signersControllerInner.wallets.find(({ name }) => name === this.walletName);
        const signer = wallet?.signers.find(({ name }) => name === this.signerName);
        void this.updateSigner(wallet, signer);
    }
    async updateSigner(wallet, signerInfo) {
        if (signerInfo?.signer === this.signer?.signer) {
            return;
        }
        this.unregisterSignerReplacer?.();
        this.unregisterSignerReplacer = undefined;
        if (signerInfo && (await signerInfo.signer.isConnected())) {
            this.wallet = wallet;
            this.signer = signerInfo;
            this.unregisterSignerReplacer?.();
            this.unregisterSignerReplacer = signerInfo.signer.onReplaced(() => {
                void this.signersControllerInner.refresh();
            });
        }
        else {
            this.wallet = undefined;
            this.signer = undefined;
        }
    }
    render() {
        return html `<div
      class="background"
      @click=${(event) => {
            if (event.target === event.currentTarget) {
                this.onClose();
            }
        }}
      @close=${(event) => {
            event.stopPropagation();
            this.onClose(event.callback);
        }}
      @updated=${() => this.updated()}
    >
      <div class="main" ${ref(this.mainRef)}>
        ${this.wallet && this.signer
            ? html `
              <ccc-connected-scene
                ?hideMark=${this.hideMark}
                .wallet=${this.wallet}
                .signer=${this.signer.signer}
                .clientOptions=${this.clientOptions}
                @disconnect=${() => this.disconnect()}
                @select-client=${(e) => this.setClient(e.client)}
                ${ref(this.bodyRef)}
              ></ccc-connected-scene>
            `
            : html `
              <ccc-selecting-scene
                .wallets=${this.signersControllerInner.wallets}
                @connected=${({ walletName, signerName }) => {
                this.walletName = walletName;
                this.signerName = signerName;
                this.refreshSigner();
                this.saveConnection();
            }}
                ${ref(this.bodyRef)}
              ></ccc-selecting-scene>
            `}
      </div>
    </div>`;
    }
    onClose(onClosed) {
        if (this.mainRef.value) {
            this.mainRef.value.style.height = "0";
        }
        setTimeout(() => {
            this.dispatchEvent(new CloseEvent());
            this.bodyRef.value?.onClose?.();
            onClosed?.();
        }, 150);
    }
    updated() {
        if (!this.mainRef.value) {
            return;
        }
        this.mainRef.value.style.height = `${this.bodyRef.value?.clientHeight ?? 0}px`;
    }
};
